import{_ as e,o as d,c as a,a3 as o}from"./chunks/framework.BlfGB29P.js";const x=JSON.parse('{"title":"React 与 Next.js 扩展 API 索引","description":"速查本手册 React/Next 扩展轨（非主线）实际讲过的 Hooks Chat、App Router/BFF 边界与可选 AI SDK 对照点及正文链接。","frontmatter":{"title":"React 与 Next.js 扩展 API 索引","description":"速查本手册 React/Next 扩展轨（非主线）实际讲过的 Hooks Chat、App Router/BFF 边界与可选 AI SDK 对照点及正文链接。","outline":[2,3],"article":{"type":"index","structure":"index"}},"headers":[],"relativePath":"ts-ai/appendix/api-index/react-next-api-index.md","filePath":"ts-ai/appendix/api-index/react-next-api-index.md","lastUpdated":1786166505000}'),r={name:"ts-ai/appendix/api-index/react-next-api-index.md"};function c(n,t,s,i,h,u){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="react-与-next-js-扩展-api-索引" tabindex="-1">React 与 Next.js 扩展 API 索引 <a class="header-anchor" href="#react-与-next-js-扩展-api-索引" aria-label="Permalink to &quot;React 与 Next.js 扩展 API 索引&quot;">​</a></h1><blockquote><p>作者：cursor-grok-4.5</p></blockquote><p>本索引帮助你从 Hook、Route Handler 或 AI SDK 对照名跳回 <code>docs/ts-ai/integration/react-next</code> 正文。本组是<strong>扩展轨、非主线</strong>：默认交付仍是 Nuxt + Nest 产品事件；本组默认实现是自建 <code>useAgentChat</code>，<strong>不是</strong> Vercel AI SDK。</p><h2 id="_1-索引范围与排除-明确非主线" tabindex="-1">1. 索引范围与排除（明确非主线） <a class="header-anchor" href="#_1-索引范围与排除-明确非主线" aria-label="Permalink to &quot;1. 索引范围与排除（明确非主线）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>包含</th><th>排除</th></tr></thead><tbody><tr><td><code>react-next/</code> 扩展文中实际讲授的 Hooks、App Router/BFF、选型与迁移映射</td><td>Vue/Nuxt 主线完整 Chat（见 <a href="/ts-ai/appendix/api-index/vue-nuxt-ai-api-index">Vue 与 Nuxt AI API 索引</a>）</td></tr><tr><td>与主线同名的 <code>ProductEvent</code> / reducer 共享思路；可选 AI SDK 对照点（仅正文出现）</td><td>把 AI SDK Data Stream 或 RSC streaming 当作默认产品 SSE；在 Server Component 挂起整次 Agent 流</td></tr><tr><td>直连 / <code>rewrites</code> / Route Handler 三种拓扑</td><td>完整 Markdown/上传教程、生产级重连游标实现（协议细节跟主线协议篇）</td></tr></tbody></table><p>学习优先级：先完成 Nuxt 主线，再按需读本组做对照或迁移。查 API 时以共享事件契约为准，禁止为 Next 改写 Nest 事件名。</p><h2 id="_2-包与入口对象" tabindex="-1">2. 包与入口对象 <a class="header-anchor" href="#_2-包与入口对象" aria-label="Permalink to &quot;2. 包与入口对象&quot;">​</a></h2><table tabindex="0"><thead><tr><th>包 / 入口</th><th>本手册常用对象</th><th>正文</th></tr></thead><tbody><tr><td><code>react</code>（Client）</td><td><code>useState</code> / <code>useRef</code> / <code>useCallback</code> / <code>useEffect</code> / <code>useMemo</code></td><td><a href="/ts-ai/integration/react-next/react-hooks-agent-chat">Hooks Chat</a>、<a href="/ts-ai/integration/react-next/vue-react-state-comparison">状态对照</a></td></tr><tr><td><code>@/lib/use-agent-chat</code>（教学路径）</td><td>自建 <code>useAgentChat</code>——本组 Chat 入口对象</td><td><a href="/ts-ai/integration/react-next/react-hooks-agent-chat">Hooks Chat</a></td></tr><tr><td><code>TicketAssistantChat</code></td><td>工单 Chat Client 组件组装入口</td><td>同上；<a href="/ts-ai/integration/react-next/nextjs-app-router">App Router</a></td></tr><tr><td>Web 原生</td><td><code>fetch</code> + <code>ReadableStream</code> + <code>AbortController</code> + <code>TextDecoder</code>；<strong>拒绝</strong>带 Token 场景用裸 <code>EventSource</code></td><td><a href="/ts-ai/integration/react-next/react-hooks-agent-chat">Hooks Chat</a>、<a href="/ts-ai/integration/react-next/nextjs-nestjs-integration">对接</a></td></tr><tr><td><code>next/headers</code> → <code>cookies</code></td><td>BFF 读 httpOnly Cookie（例：<code>access_token</code>）</td><td><a href="/ts-ai/integration/react-next/nextjs-app-router">App Router</a>、<a href="/ts-ai/integration/react-next/nextjs-nestjs-integration">Next↔Nest</a></td></tr><tr><td><code>app/api/.../route.ts</code></td><td>Route Handler：<code>GET</code>/<code>POST</code> 代理；<code>runtime = &quot;nodejs&quot;</code>；<code>dynamic = &quot;force-dynamic&quot;</code></td><td><a href="/ts-ai/integration/react-next/nextjs-app-router">App Router</a></td></tr><tr><td>建议共享包 <code>packages/product-events</code></td><td><code>ProductEvent</code> + <code>reduceAgentChat</code>（与 Nuxt 共用）</td><td><a href="/ts-ai/integration/react-next/nuxt-nextjs-migration">迁移</a></td></tr><tr><td><code>ai</code>（可选，非默认）</td><td>Vercel AI SDK：<code>useChat</code> / <code>streamText</code> 等对照</td><td><a href="/ts-ai/integration/react-next/vercel-ai-sdk">Vercel AI SDK</a></td></tr><tr><td>环境变量</td><td><code>NEST_BASE_URL</code>（服务端）、<code>NEXT_PUBLIC_NEST_BASE_URL</code>（仅直连拓扑）</td><td><a href="/ts-ai/integration/react-next/nextjs-nestjs-integration">Next↔Nest</a></td></tr></tbody></table><p>主线对等入口（概念）：Vue <code>useAgentChat</code> composable——能力对等 <code>send</code> / stream / <code>cancel</code> / <code>messages</code> / <code>runStatus</code>。</p><h2 id="_3-核心-api-家族" tabindex="-1">3. 核心 API 家族 <a class="header-anchor" href="#_3-核心-api-家族" aria-label="Permalink to &quot;3. 核心 API 家族&quot;">​</a></h2><h3 id="_3-1-hooks-chat-状态" tabindex="-1">3.1 Hooks Chat 状态 <a class="header-anchor" href="#_3-1-hooks-chat-状态" aria-label="Permalink to &quot;3.1 Hooks Chat 状态&quot;">​</a></h3><table tabindex="0"><thead><tr><th>API</th><th>用途</th><th>关键点</th><th>正文</th></tr></thead><tbody><tr><td><code>useAgentChat</code></td><td>创建 Run、读 SSE、取消</td><td>选项：<code>createRunUrl</code> / <code>streamUrl</code> / <code>threadId</code> / <code>getAccessToken?</code>；必须 <code>&quot;use client&quot;</code></td><td><a href="/ts-ai/integration/react-next/react-hooks-agent-chat">Hooks Chat</a></td></tr><tr><td><code>UseAgentChatOptions</code> / <code>UseAgentChatReturn</code></td><td>Hook 契约</td><td>返回：<code>messages</code>、<code>runStatus</code>、<code>runId</code>、<code>error</code>、<code>isBusy</code>、<code>send</code>、<code>cancel</code></td><td>同上</td></tr><tr><td><code>send(text)</code> / <code>cancel()</code></td><td>发送与本地中止</td><td><code>send</code>：写 user → POST Run → <code>for await</code> SSE；先 abort 上一次；卸载 <code>useEffect</code> cleanup 调 <code>cancel</code></td><td>同上</td></tr><tr><td><code>reduceAgentChat</code> / <code>patchToolMessage</code></td><td>纯函数状态机</td><td>框架无关、可单测；与 Vue 共用同一包；tool 按 <code>toolCallId</code> 更新</td><td>同上；<a href="/ts-ai/integration/react-next/nuxt-nextjs-migration">迁移</a></td></tr><tr><td><code>readSseStream</code></td><td><code>ReadableStream</code> → <code>ProductEvent</code> 异步生成器</td><td>半包缓冲；<code>signal</code> → <code>reader.cancel()</code></td><td><a href="/ts-ai/integration/react-next/react-hooks-agent-chat">Hooks Chat</a>；细节见 <a href="/ts-ai/integration/interaction-protocols/stream-event-parsing">流事件解析</a></td></tr><tr><td><code>AgentChatState</code> / <code>RunStatus</code> / <code>ChatMessage</code></td><td>状态形状</td><td>Run：<code>idle|streaming|tool|completed|failed|cancelled</code>；<code>isBusy</code> = <code>streaming||tool</code></td><td><a href="/ts-ai/integration/react-next/react-hooks-agent-chat">Hooks Chat</a></td></tr><tr><td><code>applyMessageDelta</code> / <code>useTicketRunStatus</code> / <code>reduceStatus</code>（示例）</td><td>Vue↔React 对照练习</td><td>函数式更新；禁止 <code>push</code> 就地改</td><td><a href="/ts-ai/integration/react-next/vue-react-state-comparison">状态对照</a></td></tr><tr><td><code>startTransition</code>（可选）</td><td>高频 delta 降输入抢占</td><td><strong>不改</strong>事件契约；非必须</td><td><a href="/ts-ai/integration/react-next/vue-react-state-comparison">状态对照</a>、<a href="/ts-ai/integration/react-next/nuxt-nextjs-migration">迁移</a></td></tr></tbody></table><p>刻意不做：Vercel <code>useChat</code> 作默认路径；完整 Markdown/上传；在 RSC 调用本 Hook。</p><h3 id="_3-2-app-router-route-handler-边界" tabindex="-1">3.2 App Router / Route Handler 边界 <a class="header-anchor" href="#_3-2-app-router-route-handler-边界" aria-label="Permalink to &quot;3.2 App Router / Route Handler 边界&quot;">​</a></h3><table tabindex="0"><thead><tr><th>API</th><th>用途</th><th>关键点</th><th>正文</th></tr></thead><tbody><tr><td>Server Component（RSC）</td><td>SSR 壳：标题、权限、<code>threadId</code></td><td>可 <code>async</code>；<strong>不能</strong> <code>useState</code>/Chat Hook；禁止 RSC 挂起整次 Agent SSE</td><td><a href="/ts-ai/integration/react-next/nextjs-app-router">App Router</a></td></tr><tr><td>Client Component + <code>&quot;use client&quot;</code></td><td>流式 Chat 状态机岛屿</td><td>唯一允许 <code>useAgentChat</code> / 浏览器长连接的位置；对等 Nuxt <code>&lt;ClientOnly&gt;</code></td><td>同上；<a href="/ts-ai/integration/react-next/react-hooks-agent-chat">Hooks</a></td></tr><tr><td>Route Handler <code>GET .../runs/[runId]/stream</code></td><td>SSE 代理 BFF</td><td><code>cookies()</code> → <code>Authorization</code>；<code>signal: request.signal</code>；透传 <code>upstream.body</code>；<strong>不改写事件名</strong></td><td><a href="/ts-ai/integration/react-next/nextjs-app-router">App Router</a>、<a href="/ts-ai/integration/react-next/nextjs-nestjs-integration">对接</a></td></tr><tr><td>Route Handler <code>POST .../threads/[threadId]/runs</code></td><td>创建 Run 的 BFF</td><td>Cookie 换票；透传 status/Content-Type；<strong>Agent 仍在 Nest</strong></td><td><a href="/ts-ai/integration/react-next/nextjs-nestjs-integration">对接</a></td></tr><tr><td><code>runtime = &quot;nodejs&quot;</code> / <code>dynamic = &quot;force-dynamic&quot;</code></td><td>流式代理运行时</td><td>优先于 <code>edge</code>；禁止静态化代理路由</td><td><a href="/ts-ai/integration/react-next/nextjs-app-router">App Router</a></td></tr><tr><td>拓扑 A/B/C：直连 / <code>rewrites</code> / BFF</td><td>Next↔Nest 接入选型</td><td>A：公开 Nest 基址 + CORS；B：<code>next.config</code> rewrite；C：Handler 换票/审计</td><td><a href="/ts-ai/integration/react-next/nextjs-nestjs-integration">对接</a>、<a href="/ts-ai/integration/react-next/nuxt-nextjs-selection">选型</a></td></tr><tr><td>Streaming RSC / Suspense / <code>use</code></td><td>服务器 HTML 分片</td><td><strong>不是</strong>产品 SSE；禁止用其替代 <code>message.delta</code></td><td><a href="/ts-ai/integration/react-next/nextjs-app-router">App Router</a></td></tr><tr><td>路径映射（迁移）</td><td>Nuxt → App Router</td><td><code>pages</code>→<code>app/.../page.tsx</code>；<code>server/routes</code>→<code>route.ts</code>；Chat 必须 Client</td><td><a href="/ts-ai/integration/react-next/nuxt-nextjs-migration">迁移</a></td></tr></tbody></table><h3 id="_3-3-ai-sdk-对照点-若正文有" tabindex="-1">3.3 AI SDK 对照点（若正文有） <a class="header-anchor" href="#_3-3-ai-sdk-对照点-若正文有" aria-label="Permalink to &quot;3.3 AI SDK 对照点（若正文有）&quot;">​</a></h3><p>仅 <a href="/ts-ai/integration/react-next/vercel-ai-sdk">Vercel AI SDK</a> 出现；默认结论：<strong>不用</strong>，坚持自建 <code>useAgentChat</code>。</p><table tabindex="0"><thead><tr><th>API</th><th>用途</th><th>关键点</th><th>正文</th></tr></thead><tbody><tr><td><code>ai</code> 包 / Data Stream / UI Message 流</td><td>可选适配层，非默认契约</td><td>优化「Next Route 直连模型」；不适配「浏览器↔Nest Agent」默认路径</td><td><a href="/ts-ai/integration/react-next/vercel-ai-sdk">Vercel AI SDK</a></td></tr><tr><td><code>useChat</code> / <code>useCompletion</code> / <code>stop()</code></td><td>SDK 客户端对照</td><td>对照 <code>messages</code>/<code>status</code>/tool invocations；<code>stop</code> 须能传到 Nest abort 并对齐 <code>run.cancelled</code></td><td>同上；Hooks 文明确排除默认 <code>useChat</code></td></tr><tr><td><code>streamText</code> / <code>streamUI</code></td><td>服务端流式能力（点名）</td><td>方案 B（Next 内调模型）偏离手册架构，仅原型；<code>streamUI</code> 无完整教程</td><td>同上</td></tr><tr><td><code>productEventToSdkData</code>（示意）</td><td>产品事件 → SDK 自定义 data 帧</td><td><code>run.started</code>→<code>data-run-started</code>；<code>message.delta</code>→<code>text-delta</code>；帧格式随 SDK 版本变</td><td>同上</td></tr><tr><td>方案 A / B / C</td><td>自建 Hook / Next <code>streamText</code> / Nest+适配层</td><td><strong>默认 A</strong>；强制 SDK → C + 验收（覆盖 <code>tool.*</code> 与 cancel）</td><td>同上；<a href="/ts-ai/integration/react-next/nuxt-nextjs-selection">选型</a></td></tr></tbody></table><p>正文未展开完整教学：<code>createUIMessageStream</code>、<code>DefaultChatTransport</code>、<code>@ai-sdk/react</code> 安装步骤等——只有评估与映射示意。Nest 已通则勿引入 SDK；多前端应共享事件包。</p><h2 id="_4-事件、错误与配置速查" tabindex="-1">4. 事件、错误与配置速查 <a class="header-anchor" href="#_4-事件、错误与配置速查" aria-label="Permalink to &quot;4. 事件、错误与配置速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>主题</th><th>关键项</th><th>放哪里处理</th><th>正文</th></tr></thead><tbody><tr><td>产品事件</td><td><code>ProductEvent</code>：<code>run.started</code>、<code>message.delta</code>、<code>tool.started</code>/<code>completed</code>/<code>failed</code>、<code>run.completed</code>/<code>failed</code>/<code>cancelled</code></td><td><code>reduceAgentChat</code>；字段以 <code>data</code> 为准；与 Nuxt 同名</td><td><a href="/ts-ai/integration/react-next/react-hooks-agent-chat">Hooks</a>、<a href="/ts-ai/integration/interaction-protocols/message-run-tool-call-events">协议权威</a></td></tr><tr><td>SSE 帧</td><td><code>event:</code> / <code>data:</code> / <code>\\n\\n</code>；<code>Accept: text/event-stream</code></td><td><code>readSseStream</code>；半包与心跳细节外链协议篇</td><td><a href="/ts-ai/integration/react-next/react-hooks-agent-chat">Hooks</a>、<a href="/ts-ai/integration/interaction-protocols/stream-event-parsing">流事件解析</a></td></tr><tr><td>客户端错误</td><td><code>CLIENT_STREAM_ERROR</code>、<code>create_run_failed:{status}</code>、<code>stream_failed:{status}</code></td><td>abort 以外异常 → 合成 <code>run.failed</code></td><td><a href="/ts-ai/integration/react-next/react-hooks-agent-chat">Hooks Chat</a></td></tr><tr><td>鉴权错误</td><td><code>UNAUTHORIZED</code> + 401；Nest <code>{ code, message }</code></td><td>BFF 无 Token；<strong>勿吞</strong>上游 body</td><td><a href="/ts-ai/integration/react-next/nextjs-app-router">App Router</a>、<a href="/ts-ai/integration/react-next/nextjs-nestjs-integration">对接</a></td></tr><tr><td>鉴权模式</td><td>Bearer / Cookie / Cookie→Bearer</td><td><code>getAccessToken</code>；<code>credentials: &#39;include&#39;</code>；BFF 只把 Bearer 打到 Nest</td><td><a href="/ts-ai/integration/react-next/nextjs-nestjs-integration">对接</a></td></tr><tr><td>代理头</td><td><code>X-Accel-Buffering: no</code>、<code>Cache-Control: no-cache</code>、<code>Connection: keep-alive</code></td><td>防 SSE 缓冲；Nginx 需关闭 buffering</td><td><a href="/ts-ai/integration/react-next/nextjs-app-router">App Router</a>、<a href="/ts-ai/integration/react-next/nextjs-nestjs-integration">对接</a></td></tr><tr><td>REST 表面</td><td><code>POST /v1/threads/{threadId}/runs</code>、<code>GET /v1/runs/{runId}/stream</code></td><td>经 <code>/api/nest/...</code> 或直连</td><td><a href="/ts-ai/integration/react-next/react-hooks-agent-chat">Hooks</a>、<a href="/ts-ai/integration/react-next/nextjs-nestjs-integration">对接</a></td></tr><tr><td>常见失败</td><td>delta 加倍、取消后仍 setState、EventSource 无 Token、Strict Mode 双请求、RSC 调 Hook</td><td>cleanup 必须可重入 abort</td><td><a href="/ts-ai/integration/react-next/react-hooks-agent-chat">Hooks</a>、<a href="/ts-ai/integration/react-next/vue-react-state-comparison">状态对照</a></td></tr></tbody></table><p>取消语义：<code>AbortController</code>、新 <code>send</code> 前 abort、本地 <code>run.cancelled</code>/<code>client_abort</code>。完整重连/去重以主线 <a href="/ts-ai/integration/interaction-protocols/cancellation-reconnection-deduplication">取消与重连</a> 为准（本组未完整实现）。</p><h2 id="_5-关联章节" tabindex="-1">5. 关联章节 <a class="header-anchor" href="#_5-关联章节" aria-label="Permalink to &quot;5. 关联章节&quot;">​</a></h2><table tabindex="0"><thead><tr><th>章节</th><th>用本索引时怎么用</th></tr></thead><tbody><tr><td><a href="/ts-ai/integration/react-next/">React / Next 总览</a></td><td>确认扩展定位与组内阅读顺序</td></tr><tr><td><a href="/ts-ai/integration/react-next/nuxt-nextjs-selection">选型</a> → <a href="/ts-ai/integration/react-next/vue-react-state-comparison">状态对照</a> → <a href="/ts-ai/integration/react-next/react-hooks-agent-chat">Hooks</a> → <a href="/ts-ai/integration/react-next/nextjs-app-router">App Router</a></td><td>扩展轨推荐路径</td></tr><tr><td><a href="/ts-ai/integration/react-next/nextjs-nestjs-integration">Next↔Nest 对接</a> / <a href="/ts-ai/integration/react-next/nuxt-nextjs-migration">迁移</a></td><td>拓扑与 Nuxt→Next 映射</td></tr><tr><td><a href="/ts-ai/integration/react-next/vercel-ai-sdk">Vercel AI SDK</a></td><td>仅在强制 SDK 时评估方案 C</td></tr><tr><td><a href="/ts-ai/appendix/api-index/vue-nuxt-ai-api-index">Vue 与 Nuxt AI API 索引</a></td><td><strong>主线</strong> API；事件与 reducer 应对齐</td></tr><tr><td><a href="/ts-ai/integration/interaction-protocols/">交互协议</a></td><td><code>ProductEvent</code> 字段、SSE 解析、取消重连权威</td></tr><tr><td><a href="/ts-ai/appendix/api-index/nestjs-api-index">NestJS API 索引</a></td><td>后端 REST/SSE 入口</td></tr><tr><td><a href="/ts-ai/appendix/references/official-resources">官方资料索引</a></td><td>本索引未收录的 API，以官方文档为准</td></tr><tr><td><a href="/ts-ai/integration/assembly/assembly-recipes-checklist">全栈集成组装配方</a></td><td>主线能力验收；扩展轨不替代主线勾选</td></tr></tbody></table>',24)])])}const p=e(r,[["render",c]]);export{x as __pageData,p as default};
